WITH enriched AS (SELECT *, AVG(sqft) OVER w_running sqft_avg_6_prior, ROW_NUMBER() OVER (ORDER BY opened_date DESC, id) seq_no, NTILE(5) OVER (PARTITION BY city ORDER BY sqft, id) sqft_bucket FROM stores WHERE region NOT IN ('South', 'West') WINDOW w_running AS (PARTITION BY region, city ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)) SELECT city, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, COUNT_IF(city = 'Berlin') AS berlin_events, SIZE(COLLECT_SET(region)) AS num_regions, SIZE(COLLECT_SET(city)) AS num_cities, COUNT(DISTINCT city) AS distinct_cities FROM enriched GROUP BY city, quarter_start HAVING num_cities > 1;
